import numpy as np
import pandas as pd
from datetime import datetime, timezone
import pytz

def r_as_POSIXct(x, tz="", **kwargs):
    """
    Convert to POSIXct (datetime with timezone).

    Parameters:
    x: input (string, list of strings, POSIXct, numeric, etc.)
    tz: timezone string (default "")
    **kwargs: additional arguments (origin, format, etc.)

    Returns:
    pandas.Timestamp or list of pandas.Timestamp objects
    """

    # Handle POSIXct input (already a Timestamp or list of Timestamps)
    if isinstance(x, pd.Timestamp):
        if tz == "":
            return x
        else:
            # Convert to specified timezone
            if x.tz is None:
                return x.tz_localize(tz)
            else:
                return x.tz_convert(tz)

    # Handle list of Timestamps
    if isinstance(x, list) and len(x) > 0 and isinstance(x[0], pd.Timestamp):
        if tz == "":
            return x
        else:
            return [t.tz_localize(tz) if t.tz is None else t.tz_convert(tz) for t in x]

    # Handle None/null input
    if x is None:
        return []

    # Handle numeric input (seconds since epoch)
    if isinstance(x, (int, float, np.integer, np.floating)):
        origin = kwargs.get('origin', '1970-01-01')
        origin_dt = pd.to_datetime(origin)
        dt = origin_dt + pd.Timedelta(seconds=float(x))

        if tz and tz != "":
            try:
                tz_obj = pytz.timezone(tz)
                dt = dt.tz_localize('UTC').tz_convert(tz_obj)
            except:
                dt = dt.tz_localize(tz)
        else:
            if dt.tz is None:
                dt = dt.tz_localize('UTC')

        return dt

    # Handle numeric array input
    if isinstance(x, np.ndarray) and np.issubdtype(x.dtype, np.number):
        origin = kwargs.get('origin', '1970-01-01')
        origin_dt = pd.to_datetime(origin)
        result = []
        for val in x:
            if np.isnan(val):
                result.append(pd.NaT)
            else:
                dt = origin_dt + pd.Timedelta(seconds=float(val))

                if tz and tz != "":
                    try:
                        tz_obj = pytz.timezone(tz)
                        dt = dt.tz_localize('UTC').tz_convert(tz_obj)
                    except:
                        dt = dt.tz_localize(tz)
                else:
                    if dt.tz is None:
                        dt = dt.tz_localize('UTC')

                result.append(dt)

        if len(result) == 1:
            return result[0]
        return result

    # Handle character input (string or list of strings)
    if isinstance(x, str):
        x = [x]

    if isinstance(x, list) and all(isinstance(item, str) for item in x):
        # Parse as datetime string, treating as naive local time in the given timezone
        result = []
        for date_str in x:
            try:
                # Parse the datetime string as naive (no timezone)
                dt = pd.to_datetime(date_str)

                # Apply timezone if specified
                if tz and tz != "":
                    try:
                        tz_obj = pytz.timezone(tz)
                        # Localize as the given timezone (not UTC conversion)
                        dt = dt.tz_localize(tz_obj)
                    except:
                        dt = dt.tz_localize(tz)
                else:
                    # Default to UTC if no timezone specified
                    if dt.tz is None:
                        dt = dt.tz_localize('UTC')

                result.append(dt)
            except:
                result.append(pd.NaT)

        if len(result) == 1:
            return result[0]
        return result

    # Handle logical input that is all NA
    if isinstance(x, np.ndarray) and x.dtype == bool:
        if np.all(np.isnan(x.astype(float))):
            return []

    # If we can't convert, raise an error
    raise TypeError(f"do not know how to convert '{type(x).__name__}' to class 'POSIXct'")
